\[\begin{align}
\mathbf{a} &= \alpha R\hat{\mathbf{3}} - R\hat{\mathbf{z}}
\tag{1}\\
&= \alpha R\sin\theta\hat{\mathbf{x}} + R(\alpha\cos\theta - 1)\hat{\mathbf{z}}
\notag\\
&= R\sin\theta\hat{\mathbf{1}} + R(\alpha - \cos\theta)\hat{\mathbf{3}}
\notag
\end{align}\]

\[\begin{align}
\boldsymbol{\tau}_\mathrm{ext} &= \mathbf{a} \times (N\hat{\mathbf{z}} + \mathbf{F}_f)
\tag{9}\\
&= (\alpha R\hat{\mathbf{3}} - R\hat{\mathbf{z}}) \times (N\hat{\mathbf{z}} + F_{f,x}\hat{\mathbf{x}} + F_{f,y}\hat{\mathbf{y}})
\notag\\
&= \alpha RN\hat{\mathbf{3}} \times \hat{\mathbf{z}} + \alpha R(\sin\theta\hat{\mathbf{x}} + \cos\theta\hat{\mathbf{z}}) \times (F_{f,x}\hat{\mathbf{x}} + F_{f,y}\hat{\mathbf{y}}) - R\hat{\mathbf{z}} \times (F_{f,x}\hat{\mathbf{x}} + F_{f,y}\hat{\mathbf{y}})
\notag\\
&= -\alpha RN\sin\theta\hat{\mathbf{y}} + \alpha R\sin\theta F_{f,y}\hat{\mathbf{z}} + \alpha R\cos\theta F_{f,x}\hat{\mathbf{y}} - \alpha R\cos\theta F_{f,y}\hat{\mathbf{x}} - RF_{f,x}\hat{\mathbf{y}} + RF_{f,x}\hat{\mathbf{x}}
\notag\\
&= RF_{f,y}(1 - \alpha\cos\theta)\hat{\mathbf{x}} + \left[RF_{f,x}(\alpha\cos\theta - 1) - \alpha RN\sin\theta\right]\hat{\mathbf{y}} + \alpha R\sin\theta F_{f,y}\hat{\mathbf{z}}
\tag{10}
\end{align}\]

\[\begin{align*}
\dot{\mathbf{s}} &= \mathbf{v_A} - \boldsymbol{\omega} \times \mathbf{a}\\
&= \mathbf{v_A} - (\dot{\theta}\hat{\mathbf{2}} + \dot{\phi}\hat{\mathbf{z}} + \dot{\psi}\hat{\mathbf{3}}) \times (\alpha R\hat{\mathbf{3}} - R\hat{\mathbf{z}})\\
&= v_x\hat{\mathbf{x}} + v_y\hat{\mathbf{y}} - \left(\dot{\theta}\alpha R\hat{\mathbf{1}} - \dot{\theta}R\hat{\mathbf{z}} + \dot{\phi}\alpha R\hat{\mathbf{z}} \times \hat{\mathbf{3}} - \dot{\psi}R\hat{\mathbf{3}} \times \hat{\mathbf{z}}\right)\\
&= \left(v_x + \dot{\theta}R(1 - \alpha\cos\theta)\right)\hat{\mathbf{x}} + \left(v_y - R\sin\theta(\alpha\dot{\phi} + \dot{\psi})\right)\hat{\mathbf{y}} + \dot{\theta}\alpha R\sin\theta\hat{\mathbf{z}}
\end{align*}\]
